import * as ordersApi from './api.js'

/** The orders screen's state. Views subscribe and re-render when it changes. */
export function createStore(api = ordersApi) {
  let state = {
    orders: [],
    filter: '',
    loading: true,
    loaded: false,
    error: null,
  }
  let latestLoad = 0
  const listeners = new Set()

  function set(changes) {
    const next = { ...state, ...changes }
    // Views re-render only when something they show changed.
    if (Object.keys(changes).every((key) => next[key] === state[key])) return
    state = next
    for (const listener of listeners) listener(state)
  }

  async function load(filter = state.filter) {
    const request = ++latestLoad
    // Another filter is another list: the old rows must not show under it.
    set({
      filter,
      loading: true,
      ...(filter === state.filter ? {} : { orders: [] }),
    })
    try {
      const orders = await api.listOrders(filter)
      // A newer load started while this one was on its way: its answer wins.
      if (request !== latestLoad) return
      set({ orders, loading: false, loaded: true, error: null })
    } catch {
      if (request !== latestLoad) return
      set({
        orders: [],
        loading: false,
        error: state.loaded
          ? 'Could not refresh orders.'
          : 'Could not load orders.',
      })
    }
  }

  async function ship(id) {
    try {
      const updated = await api.updateStatus(id, 'shipped')
      set({
        orders: state.orders.map((order) =>
          order.id === updated.id ? updated : order,
        ),
        error: null,
      })
    } catch {
      set({ error: 'Could not update the order.' })
    }
  }

  return {
    get state() {
      return state
    },
    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    load,
    refresh: () => load(),
    ship,
  }
}
import { money, statusLabel, updatedAt } from './format.js'

function cell(className, text) {
  const span = document.createElement('span')
  span.className = className
  span.textContent = text
  return span
}

function row(order, onShip) {
  const item = document.createElement('li')
  item.dataset.order = order.id
  item.append(
    cell('id', order.id),
    cell('customer', order.customer),
    cell('state', statusLabel(order.status)),
    cell('total', money(order.total)),
    cell('updated', updatedAt(order.updatedAt)),
  )
  if (order.status === 'packed') {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = 'ship'
    button.textContent = 'Mark shipped'
    button.addEventListener('click', () => onShip(order.id))
    item.append(button)
  }
  return item
}

/** Draws the orders screen for `state` into the elements of `screen`. */
export function render(screen, state, { onShip }) {
  screen.status.textContent = state.loading
    ? state.loaded
      ? 'Refreshing…'
      : 'Loading orders…'
    : ''
  screen.error.textContent = state.error ?? ''
  screen.error.hidden = !state.error
  screen.empty.hidden =
    state.loading || !state.loaded || state.orders.length > 0
  screen.list.replaceChildren(
    ...state.orders.map((order) => row(order, onShip)),
  )
  for (const button of screen.filters)
    button.setAttribute(
      'aria-pressed',
      String(button.dataset.filter === state.filter),
    )
}
async function request(path, options) {
  const response = await fetch(path, options)
  if (!response.ok) throw new Error(`HTTP ${response.status} for ${path}`)
  return response.json()
}

/** The orders with the given status, or every order when `status` is empty. */
export function listOrders(status = '') {
  const query = status ? `?status=${encodeURIComponent(status)}` : ''
  return request(`/api/orders${query}`)
}

/** Sets an order's status on the server; resolves with the updated order. */
export function updateStatus(id, status) {
  return request(`/api/orders/${encodeURIComponent(id)}/status`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  })
}
import { createStore } from './store.js'
import { render } from './view.js'

const screen = {
  status: document.querySelector('#status'),
  error: document.querySelector('#error'),
  empty: document.querySelector('#empty'),
  list: document.querySelector('#orders'),
  filters: [...document.querySelectorAll('[data-filter]')],
}
const views = {
  overview: document.querySelector('#overview'),
  orders: document.querySelector('#orders-view'),
}

const store = createStore()
store.subscribe((state) => render(screen, state, { onShip: store.ship }))
render(screen, store.state, { onShip: store.ship })

for (const button of screen.filters)
  button.addEventListener('click', () => store.load(button.dataset.filter))
document
  .querySelector('#refresh')
  .addEventListener('click', () => store.refresh())

/** Shows the view the address names; opening Orders loads them. */
function route() {
  const orders = location.hash === '#/orders'
  views.overview.hidden = orders
  views.orders.hidden = !orders
  if (orders) store.load(store.state.filter)
}
window.addEventListener('hashchange', route)
route()
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createStore } from '../public/src/store.js'
import { money, statusLabel } from '../public/src/format.js'

const ORDERS = [
  { id: 'ORD-1', customer: 'A', status: 'new', total: 10, updatedAt: '' },
  { id: 'ORD-2', customer: 'B', status: 'packed', total: 20, updatedAt: '' },
]

test('loading asks for the selected filter and shows its orders', async () => {
  const asked = []
  const store = createStore({
    listOrders: async (status) => {
      asked.push(status)
      return ORDERS.filter((order) => !status || order.status === status)
    },
  })
  await store.load('packed')
  assert.deepEqual(asked, ['packed'])
  assert.equal(store.state.filter, 'packed')
  assert.deepEqual(
    store.state.orders.map((order) => order.id),
    ['ORD-2'],
  )
  assert.equal(store.state.loading, false)
})

test('a failed first load says the orders could not be loaded', async () => {
  const store = createStore({
    listOrders: async () => {
      throw new Error('HTTP 503')
    },
  })
  await store.load('')
  assert.equal(store.state.error, 'Could not load orders.')
  assert.equal(store.state.loading, false)
})

test('subscribers hear about each change', async () => {
  const store = createStore({ listOrders: async () => ORDERS })
  const seen = []
  store.subscribe((state) => seen.push(state.loading))
  await store.load('')
  assert.deepEqual(seen, [false])
})

test('statuses and totals are shown the way the team reads them', () => {
  assert.equal(statusLabel('packed'), 'Packed')
  assert.equal(money(89.5), '€89.50')
})
